  // Claim the turn SYNCHRONOUSLY — before the first `await` — so a concurrent
  // caller sees the claim and defers. `errorSignalled` is set only after the
  // response is actually delivered: `sendResponse` retries internally and
  // throws when it ultimately fails, and a failed first delivery must leave
  // the turn retryable rather than permanently suppressing every later
  // attempt (which would leave the user with NO terminal error at all —
  // strictly worse than the duplicate this latch exists to prevent).
  const delivery = this.sendResponse(
    this.buildBaseResponse({
      error: error.message,
      processedMessageIds: this.processedMessageIds,
      toolsUsed: [...this.toolsUsed],
      ...(errorCode && { errorCode }),
      ...(errorContext && { errorContext }),
    })
  );
  this.errorDelivery = delivery;
  try {
    await delivery;
    this.errorSignalled = true;
  } finally {
    // Clear the in-flight slot either way: on success `errorSignalled` now
    // holds the latch, and on failure the turn must stay retryable.
    this.errorDelivery = undefined;
  }
}

