1	/**
2	 * Model resolution and session management helpers.
3	 * Extracted from worker.ts for clarity.
4	 */
5	
6	import * as fs from "node:fs/promises";
7	import * as path from "node:path";
8	import {
9	  type ConfigProviderMeta,
10	  createLogger,
11	  type PiAiApi,
12	  resolveSdkCompat,
13	  SDK_COMPAT_PROTOCOLS,
14	} from "@lobu/core";
15	import { getModel, type Model } from "@mariozechner/pi-ai";
16	import { SessionManager } from "@mariozechner/pi-coding-agent";
17	
18	const logger = createLogger("model-resolver");
19	
20	/**
21	 * Look up a pi-ai registry model by RUNTIME-resolved provider + model strings.
22	 *
23	 * pi-ai's `getModel` is generically typed over its static `MODELS` registry
24	 * (`TProvider extends KnownProvider`, `TModelId extends keyof MODELS[TProvider]`),
25	 * so it cannot be called with the dynamic strings Lobu resolves at runtime
26	 * without a cast. Centralize that one unavoidable cast here — behind a typed
27	 * `(string, string) => Model<any> | undefined` boundary — so call sites stay
28	 * clean and the dynamic edge is explicit in exactly one place. Returns
29	 * `undefined` when the registry has no such entry (callers then build a dynamic
30	 * or cloned model).
31	 */
32	export function getModelDynamic(
33	  provider: string,
34	  modelId: string
35	): Model<any> | undefined {
36	  return getModel(provider as never, modelId as never) as
37	    | Model<any>
38	    | undefined;
39	}
40	
41	/** Hardcoded fallback map for provider base URL env vars. */
42	export const DEFAULT_PROVIDER_BASE_URL_ENV: Record<string, string> = {
43	  anthropic: "ANTHROPIC_BASE_URL",
44	  openai: "OPENAI_BASE_URL",
45	  // Dedicated key (mirrors chatgpt-oauth-module's baseUrlEnvVarName). Must stay
46	  // distinct from "openai" so the gateway's per-provider base URLs never
47	  // collide on OPENAI_BASE_URL — see chatgpt-oauth-module.ts.
48	  "openai-codex": "OPENAI_CODEX_BASE_URL",
49	  // Keyed by the gateway provider slug (config id), e.g. "gemini" — NOT
50	  // "google". registerDynamicProvider() overlays the live config values at
51	  // runtime; these stay as fallbacks for providers not in providers.json.
52	  gemini: "GEMINI_API_BASE_URL",
53	  nvidia: "NVIDIA_API_BASE_URL",
54	  "z-ai": "Z_AI_API_BASE_URL",
55	};
56	
57	/**
58	 * Default model IDs per provider, used when no explicit model is configured.
59	 * `anthropic` is intentionally absent: its default is resolved live by the
60	 * gateway (newest model from the API) and delivered via session context, so it
61	 * never rots to a retired snapshot. The remaining entries are last-ditch
62	 * fallbacks for providers not present in providers.json (config-driven
63	 * providers overlay their own defaultModel via registerDynamicProvider()).
64	 */
65	export const DEFAULT_PROVIDER_MODELS: Record<string, string> = {
