18	const logger = createLogger("model-resolver");
19	
20	/**
21	 * Look up a pi-ai registry model by RUNTIME-resolved provider + model strings.
22	 *
23	 * pi-ai's `getModel` is generically typed over its static `MODELS` registry
24	 * (`TProvider extends KnownProvider`, `TModelId extends keyof MODELS[TProvider]`),
25	 * so it cannot be called with the dynamic strings Lobu resolves at runtime
26	 * without a cast. Centralize that one unavoidable cast here — behind a typed
27	 * `(string, string) => Model<any> | undefined` boundary — so call sites stay
28	 * clean and the dynamic edge is explicit in exactly one place. Returns
29	 * `undefined` when the registry has no such entry (callers then build a dynamic
30	 * or cloned model).
31	 */
32	export function getModelDynamic(
33	  provider: string,
34	  modelId: string
35	): Model<any> | undefined {
36	  return getModel(provider as never, modelId as never) as
37	    | Model<any>
38	    | undefined;
39	}
40	
41	/** Hardcoded fallback map for provider base URL env vars. */
42	export const DEFAULT_PROVIDER_BASE_URL_ENV: Record<string, string> = {
43	  anthropic: "ANTHROPIC_BASE_URL",
44	  openai: "OPENAI_BASE_URL",
45	  // Dedicated key (mirrors chatgpt-oauth-module's baseUrlEnvVarName). Must stay
46	  // distinct from "openai" so the gateway's per-provider base URLs never
47	  // collide on OPENAI_BASE_URL — see chatgpt-oauth-module.ts.
48	  "openai-codex": "OPENAI_CODEX_BASE_URL",
49	  // Keyed by the gateway provider slug (config id), e.g. "gemini" — NOT
50	  // "google". registerDynamicProvider() overlays the live config values at
51	  // runtime; these stay as fallbacks for providers not in providers.json.
52	  gemini: "GEMINI_API_BASE_URL",
53	  nvidia: "NVIDIA_API_BASE_URL",
54	  "z-ai": "Z_AI_API_BASE_URL",
55	};
56	
57	/**
58	 * Default model IDs per provider, used when no explicit model is configured.
59	 * `anthropic` is intentionally absent: its default is resolved live by the
60	 * gateway (newest model from the API) and delivered via session context, so it
61	 * never rots to a retired snapshot. The remaining entries are last-ditch
62	 * fallbacks for providers not present in providers.json (config-driven
63	 * providers overlay their own defaultModel via registerDynamicProvider()).
64	 */
65	export const DEFAULT_PROVIDER_MODELS: Record<string, string> = {
66	  openai: "gpt-4.1",
67	  "openai-codex": "gpt-5.1-codex-max",
68	  // Keyed by gateway slug ("gemini", not "google"). Overridden at runtime by
69	  // the config-driven defaultModel via registerDynamicProvider().
70	  gemini: "gemini-2.5-flash",
71	  // NVIDIA's model registry uses the "organization/model" prefix format.
72	  nvidia: "nvidia/moonshotai/kimi-k2.6",
73	  "z-ai": "glm-4.7",
74	};
75	
76	/**
77	 * Map gateway provider slugs to model-registry provider names.
78	 * The gateway uses slugs like "z-ai" while the model registry uses "zai".
79	 */
80	export const PROVIDER_REGISTRY_ALIASES: Record<string, string> = {
81	  "z-ai": "zai",
82	};
83	
84	/**
85	 * Registry alias → pi-ai adapter, derived from the protocol registry. Lets the
86	 * model builder pick the right wire adapter for a dynamic model from just the
87	 * resolved registry alias. When an alias maps to multiple protocols (e.g.
88	 * "openai" ← openai + openai-responses), the first wins — openai-completions,
89	 * the correct default for the common OpenAI-compatible case.
90	 */
91	export const PIAI_API_BY_REGISTRY_ALIAS: Record<string, PiAiApi> =
92	  Object.fromEntries(
93	    Object.values(SDK_COMPAT_PROTOCOLS)
94	      .reverse()
95	      .map((p) => [p.registryAlias, p.api])
96	  );
97	
98	/**
99	 * Register a config-driven provider at runtime.
100	 * Extends the base URL env, default model, and registry alias maps
101	 * so resolveModelRef() and the worker can handle the provider.
102	 */
103	export function registerDynamicProvider(
104	  id: string,
105	  config: ConfigProviderMeta
106	): void {
107	  const alreadyRegistered = !!DEFAULT_PROVIDER_BASE_URL_ENV[id];
108	
109	  if (!alreadyRegistered) {
110	    DEFAULT_PROVIDER_BASE_URL_ENV[id] = config.baseUrlEnvVar;
111	  }
112	
113	  // Always update default model and alias even for pre-registered providers
114	  if (config.defaultModel && !DEFAULT_PROVIDER_MODELS[id]) {
115	    DEFAULT_PROVIDER_MODELS[id] = config.defaultModel;
116	  }
117	
118	  // Map to model registry name: explicit alias, else the protocol's registry
119	  // alias (e.g. openai-compatible → "openai", anthropic → "anthropic").
120	  if (!PROVIDER_REGISTRY_ALIASES[id]) {
121	    const alias =
122	      config.registryAlias || resolveSdkCompat(config.sdkCompat)?.registryAlias;
123	    if (alias) {
124	      PROVIDER_REGISTRY_ALIASES[id] = alias;
125	    }
126	  }
127	
128	  if (alreadyRegistered) return;
129	
130	  logger.info(
131	    `Registered dynamic provider: ${id} (baseUrlEnv=${config.baseUrlEnvVar}, sdkCompat=${config.sdkCompat || "none"})`
132	  );
133	}
134	
135	/** Shape of a dynamically-built model entry (any pi-ai wire protocol). */
136	interface DynamicModel {
137	  id: string;
