185	        `(${DEFAULT_PROVIDER_BASE_URL_ENV[rawProvider] ?? "unknown"}). ` +
186	        `Connect the provider in the agent's Providers settings, choose a model ` +
187	        `from a connected provider, or restart/redeploy the gateway if the provider is already connected.`
188	    );
189	  }
190	  return {
191	    id: modelId,
192	    name: modelId,
193	    api,
194	    provider: registryProvider,
195	    baseUrl: providerBaseUrl || "https://api.openai.com/v1",
