      getSessionContext: async () => ({
        agentInstructions: "",
        platformInstructions: "",
        networkInstructions: "",
        skillsInstructions: "",
        mcpStatus: [],
      }),
    } as any,
    undefined,
    catalog,
    settings,
  );

  const pc = await sessionContextProviderConfig(gateway);
  expect(pc.defaultProvider).toBe("byo2");
  expect(pc.defaultProviderServesModel).toBe(true);
});

