    return { model: firstReplacement, replaced: true };
  }
  // Out-of-list: replace with the first listed real+routable model; if none
  // qualifies (all sentinels / none routable), firstReplacement is undefined →
  // fail closed.
  return { model: firstReplacement, replaced: true };
}

