/**
 * Provider slug → the name the provider calls itself. Only entries whose
 * display form is not just a capitalisation of the slug need to be listed.
 */
const PROVIDER_DISPLAY_NAMES: Record<string, string> = {
  anthropic: 'Anthropic',
  openai: 'OpenAI',
  gemini: 'Google Gemini',
  google: 'Google',
  'z-ai': 'Z.ai',
  openrouter: 'OpenRouter',
  groq: 'Groq',
  mistral: 'Mistral',
  deepseek: 'DeepSeek',
  xai: 'xAI',
};

function providerDisplayName(slug: string): string {
  const known = PROVIDER_DISPLAY_NAMES[slug.toLowerCase()];
  if (known) return known;
  // `inference-provider:foo` → `foo`; then Title Case the bare slug.
  const bare = slug.includes(':') ? (slug.split(':').pop() ?? slug) : slug;
  return bare.charAt(0).toUpperCase() + bare.slice(1);
}

/**
 * Pull the human sentence out of a provider error body and say WHO produced it.
 *
 * Providers return their failures as a serialized error object, so relaying the
 * body verbatim put `400 {"type":"error","error":{...},"request_id":"req_011..."}`
 * in the user's chat — machine noise, and with no indication of which provider
 * failed (the CTA named one, the text did not). We unwrap ONE well-known
 * envelope shape (`{error:{message}}` / `{message}`) and prefix the source.
 *
 * Deliberately NOT a per-provider parser: anything that is not that envelope is
 * relayed unchanged, because a provider that sent a plain sentence already said
 * the useful thing (the quota reset time, the bad model id).
 */
function labelProviderBody(
  body: string | undefined,
  provider: string | undefined
): string | undefined {
  if (!body) return body;
  if (!provider) return body;

  // Bodies arrive as `<status> <json>` (e.g. `400 {...}`) or bare JSON. Find the
  // first brace so the status code does not defeat the parse.
  const braceAt = body.indexOf('{');
  let message = body;
  if (braceAt !== -1) {
    try {
      const parsed: unknown = JSON.parse(body.slice(braceAt));
      const inner =
        typeof parsed === 'object' && parsed !== null
          ? ((parsed as { error?: { message?: unknown }; message?: unknown })
              .error?.message ??
            (parsed as { message?: unknown }).message)
          : undefined;
      // Only accept a non-empty string; a nested object is not a sentence, and
      // falling through leaves the caller with the original body.
      if (typeof inner === 'string' && inner.trim()) message = inner.trim();
    } catch {
      // Not JSON after all (a brace inside prose) — relay the body unchanged.
    }
  }

  return `${providerDisplayName(provider)} returned an error:\n${message}`;
}

