53	 * lands on the tab that hosts the models allow-list editor, so the CTA drops
54	 * the admin exactly where they pick a model / connect a provider.
55	 *
56	 * `publicGatewayUrl` is the gateway base, which in embedded mode carries the
57	 * `/lobu` path suffix (the gateway is mounted at `/lobu` under the web app).
58	 * Admin UI routes live at the web origin (`/<slug>/agents/...`) NOT under
59	 * `/lobu`, so a trailing `/lobu` is stripped before composing the link.
60	 */
61	export async function buildAgentSettingsUrl(
62	  publicGatewayUrl: string | undefined,
63	  organizationId: string | undefined,
64	  agentId: string | undefined,
65	  // A pending manage_agents update run to review: appends `?run_id=<id>` so the
66	  // settings form prefills the proposed change for Approve/Reject (WI-0.3).
67	  opts?: { runId?: number }
68	): Promise<string | null> {
69	  if (!publicGatewayUrl || !organizationId || !agentId) return null;
70	  const slug = await getOrganizationSlug(organizationId).catch(() => null);
71	  if (!slug) return null;
72	  const webOrigin = publicGatewayUrl.replace(/\/+$/, '').replace(/\/lobu$/, '');
73	  const base = `${webOrigin}/${encodeURIComponent(slug)}/agents/${encodeURIComponent(agentId)}/settings`;
74	  return opts?.runId ? `${base}?run_id=${opts.runId}` : base;
75	}
76	
77	/**
78	 * Build a Behavior's edit URL —
79	 * `<webOrigin>/<orgSlug>/agents/<agentId>/behaviors/<behaviorId>` — the
80	 * review target for a pending `manage_behaviors` update. Mirrors
81	 * {@link buildAgentSettingsUrl}: `?run_id=<id>` prefills the Behavior edit form
82	 * with the proposed change for Approve/Reject.
83	 *
84	 * A Behavior is owned by an agent (`watchers.agent_id`), so the route is nested
85	 * under that agent — the caller passes the owning agent id (from the current
86	 * Behavior row). Returns null when any required piece is missing; the producer
87	 * falls back to the run permalink.
88	 */
89	export async function buildBehaviorSettingsUrl(
90	  publicGatewayUrl: string | undefined,
91	  organizationId: string | undefined,
92	  agentId: string | undefined,
93	  behaviorId: string | number | undefined,
94	  opts?: { runId?: number }
95	): Promise<string | null> {
96	  if (!publicGatewayUrl || !organizationId || !agentId || behaviorId == null) {
97	    return null;
98	  }
99	  const slug = await getOrganizationSlug(organizationId).catch(() => null);
100	  if (!slug) return null;
101	  const base = buildBehaviorUrl(slug, agentId, behaviorId, publicGatewayUrl);
102	  return opts?.runId ? `${base}?run_id=${opts.runId}` : base;
103	}
104	
105	/**
106	 * The provider's connector-detail path under an org: `/<orgSlug>/connectors/
107	 * <INFERENCE_ROW_KEY_PREFIX><provider>` — model providers are ordinary
108	 * connectors, so both provider CTAs land on the shared connector detail page.
109	 * The prefixed key is one path segment and contains `:`, so it is
110	 * percent-encoded (`inference-provider%3A…`); the SPA router decodes the param.
111	 * No provider → the connectors list.
112	 */
113	function providerConnectorPath(slug: string, provider?: string): string {
114	  const base = `/${encodeURIComponent(slug)}/connectors`;
115	  if (!provider) return base;
116	  return `${base}/${encodeURIComponent(`${INFERENCE_ROW_KEY_PREFIX}${provider}`)}`;
117	}
118	
119	/**
120	 * Build the org's "connect a provider" URL — the provider's connector detail
121	 * page (which hosts the create-provider form while the provider is not
122	 * connected yet) — as opposed to *picking a model* on an agent (which is
123	 * {@link buildAgentSettingsUrl}). This is the same live route the pre-enqueue
124	 * model-provider preflight links to.
125	 *
126	 * `model`/`reason`/`agentId` prefill the connect form and drive the agent
127	 * explainer banner. Returns null when any required piece is missing; callers
128	 * fall back to a non-linked message. The `/lobu` embedded-mode suffix is
129	 * stripped like the sibling builders.
130	 */
131	export async function buildProviderConnectUrl(
132	  publicGatewayUrl: string | undefined,
133	  organizationId: string | undefined,
134	  prefill?: {
135	    provider?: string;
136	    model?: string;
137	    reason?: string;
138	    agentId?: string;
139	  }
140	): Promise<string | null> {
141	  if (!publicGatewayUrl || !organizationId) return null;
142	  const slug = await getOrganizationSlug(organizationId).catch(() => null);
143	  if (!slug) return null;
144	  const webOrigin = publicGatewayUrl.replace(/\/+$/, '').replace(/\/lobu$/, '');
145	  const url = new URL(providerConnectorPath(slug, prefill?.provider), `${webOrigin}/`);
146	  if (prefill?.provider) {
147	    if (prefill.model) url.searchParams.set('model', prefill.model);
148	    if (prefill.reason) url.searchParams.set('reason', prefill.reason);
