describe("provider display names track the registry", () => {
  // The label map is a static mirror of providers.json (see the comment on
  // PROVIDER_DISPLAY_NAMES: the error path must not depend on a file read).
  // A static mirror rots silently, so assert the overlap here: any slug we DO
  // list must carry the registry's own name, or the chat says "Z.ai" while the
  // rest of the product says "z.ai".
  it("matches providers.json for every slug it claims", async () => {
    const { readFile } = await import("node:fs/promises");
    const { join } = await import("node:path");
    const raw = await readFile(
      join(__dirname, "../../../../cli/dist/providers.json"),
      "utf8"
    ).catch(() => null);
    if (!raw) return; // registry not built in this environment — nothing to pin
    const registry: { providers: Array<{ id: string; name: string }> } =
      JSON.parse(raw);

    const mismatches: string[] = [];
    for (const p of registry.providers) {
      const rendered = await renderAgentError(
        AgentErrorCode.PROVIDER_QUOTA_EXHAUSTED,
        "boom",
        resolveNothing,
        { provider: p.id }
      );
      // Only slugs we deliberately list are pinned; the rest legitimately fall
      // through to Title Case.
      const claimed = rendered.text.startsWith(`${p.name} returned an error:`);
      const titleCased = rendered.text.startsWith(
        `${p.id.charAt(0).toUpperCase()}${p.id.slice(1)} returned an error:`
      );
      if (!claimed && !titleCased) {
        mismatches.push(`${p.id}: expected "${p.name}", got "${rendered.text.split("\n")[0]}"`);
      }
    }
    expect(mismatches).toEqual([]);
  });
});
EOF
